package cn.paletale.companion;
import java.util.*;
import java.util.regex.Pattern;
/** Only explicit server whisper envelopes are accepted; public chat prefixes are rejected. */
public final class PrivateChat {
 public record Entry(String account,String peer,boolean outgoing,long time,String text,String channel,String scope,String sender,String origin){public Entry(String a,String p,boolean o,long t,String body,String c,String scope,String sender){this(a,p,o,t,body,c,scope,sender,"");}public String originKind(){if(origin!=null&&!origin.isBlank())return origin;return channelKind().equals("favorite-end")?"end":channelKind().equals("favorite-nether")?"nether":"";}public Entry(String a,String p,boolean o,long t,String body){this(a,p,o,t,body,"private","",o?"":p);}public String channelKind(){return channel==null?"private":channel;}public String senderId(){return sender==null?(outgoing?"":peer):sender;}}
 /** Land role titles are owner-defined (e.g. 牧羊人), so any short title, or none, is accepted. */
 static final Pattern LAND=Pattern.compile("^([^\\s|\\[<>]+)\\s*\\|\\s*(?:[^\\s|\\[<>»:：\\uFFFC]{1,16}\\s+)?(?:\\uFFFC|\\[[A-Za-z0-9_]{1,16} head\\])?\\s*([A-Za-z0-9_]{1,16})\\s*[»>]\\s?(.*)$");
 public static boolean scopeValid(String s){return s!=null&&!s.isBlank()&&s.length()<=100&&s.codePoints().noneMatch(c->Character.isWhitespace(c)||Character.isISOControl(c)||"/\\|<>".indexOf(c)>=0);}

 public static String command(String peer,String text){if(peer==null||text==null||text.isBlank()||text.contains("\n")||text.contains("\r"))throw new IllegalArgumentException();if(peer.startsWith("领地:")||peer.startsWith("国家:")){String scope=peer.substring(3);if(!scopeValid(scope))throw new IllegalArgumentException();return (peer.startsWith("领地:")?"l":"n")+" chat "+scope+" "+text;}if(!peer.matches("[A-Za-z0-9_]{1,16}"))throw new IllegalArgumentException();return "msg "+peer+" "+text;}

 public static Optional<Entry> parse(String raw,String me,long time,String account){if(raw==null||raw.length()>4096)return Optional.empty();String clean=LedgerParser.clean(raw);for(int type=0;type<2;type++){var rules=ChatRules.current();var group=(type==0?rules.nation():LAND).matcher(clean);if(group.matches()){String scope=group.group(1).strip(),sender=group.group(2),body=group.group(3);if(!scopeValid(scope)||body.isEmpty()||body.length()>2000||rules.reservedScope(scope))return Optional.empty();return Optional.of(new Entry(account,(type==0?"国家:":"领地:")+scope,sender.equalsIgnoreCase(me),time,body,type==0?"nation":"land",scope,sender));}}var m=ChatRules.current().envelope().matcher(clean);if(!m.matches())return Optional.empty();String self=ChatRules.current().self(),sender=m.group(1),target=m.group(2),body=m.group(3);boolean out=sender.equals(self)||!target.equals(self)&&sender.equalsIgnoreCase(me),in=!sender.equals(self)&&(target.equals(self)||target.equalsIgnoreCase(me));String peer=out?target:sender;if(out==in||!peer.matches("[A-Za-z0-9_]{1,16}")||body.isEmpty()||body.length()>2000)return Optional.empty();return Optional.of(new Entry(account,peer,out,time,body));}
 /** Only a known favorite immediately before the global-chat colon is accepted. */
 public static Optional<Entry> favoriteGlobal(String raw,Set<String> favorites,long time,String account){if(raw==null||raw.length()>4096||favorites.isEmpty())return Optional.empty();var rules=ChatRules.current();var m=rules.global().matcher(LedgerParser.clean(raw));if(!m.matches()||m.group(4).isEmpty()||m.group(4).length()>2000||favorites.stream().noneMatch(n->n.equalsIgnoreCase(m.group(3))))return Optional.empty();String sender=m.group(3),marker=m.group(2),prefix=m.group(1),origin=rules.origin(prefix,marker);return Optional.of(new Entry(account,"收藏:"+sender,false,time,m.group(4),marker.equals(rules.tradeMarker())?"favorite-trade":"favorite-global",sender,sender,origin));}

 public static Optional<Entry> official(String raw,long time,String account){if(raw==null||raw.length()>4096)return Optional.empty();String value=LedgerParser.clean(raw);var match=ChatRules.current().official().matcher(value);if(!match.matches()||match.group(2).isBlank()||match.group(2).length()>2000)return Optional.empty();return Optional.of(new Entry(account,"官方",false,time,match.group(2),"official","",match.group(1)));}
 public static List<Run> officialRuns(List<Entry> entries){var groups=new LinkedHashMap<String,Run>();for(var e:entries){String key=e.senderId()+"\0"+e.text();var old=groups.get(key);groups.put(key,old==null?new Run(e,e.time(),1):new Run(old.first(),Math.max(old.end(),e.time()),old.count()+1));}return groups.values().stream().sorted(Comparator.comparingLong(Run::end)).toList();}
 public record Run(Entry first,long end,int count){}
 public static List<Run> runs(List<Entry> entries){var out=new ArrayList<Run>();var trades=new HashMap<String,Integer>();Entry previous=null;for(var e:entries){Entry prior=previous;previous=e;if(prior!=null&&ChatTimeBreak.needed(prior.time(),e.time()))trades.clear();if(e.channelKind().equals("favorite-trade")){String key=e.senderId().toLowerCase(Locale.ROOT)+"\0"+e.originKind()+"\0"+e.text();Integer index=trades.get(key);if(index!=null){var last=out.get(index);{out.set(index,new Run(last.first(),e.time(),last.count()+1));continue;}}trades.put(key,out.size());out.add(new Run(e,e.time(),1));continue;}if(!out.isEmpty()){var last=out.getLast();var p=last.first();if(prior!=null&&prior.channelKind().equals(e.channelKind())&&prior.text().equals(e.text())&&p.peer().equalsIgnoreCase(e.peer())&&p.channelKind().equals(e.channelKind())&&p.originKind().equals(e.originKind())&&p.outgoing()==e.outgoing()&&p.senderId().equalsIgnoreCase(e.senderId())&&p.text().equals(e.text())&&!ChatTimeBreak.needed(last.end(),e.time())){out.set(out.size()-1,new Run(p,e.time(),last.count()+1));continue;}}out.add(new Run(e,e.time(),1));}return List.copyOf(out);}
 public static List<Entry> appendLive(List<Entry> old,Entry entry,String account){var rows=new ArrayList<>(old);if(valid(entry,account))rows.add(entry);return merge(List.of(),rows,account);}
 /** Import is a multiset union: retain same-second occurrences, but re-import adds none. */
 public static List<Entry> merge(List<Entry> old,List<Entry> incoming,String account){var existing=new HashMap<String,Integer>();var occurrences=new HashMap<String,Integer>();var rows=new ArrayList<Entry>();for(var e:old)if(valid(e,account)){rows.add(e);existing.merge(key(e,e.time()/1000),1,Integer::sum);}for(var e:incoming){if(!valid(e,account))continue;String k=key(e,e.time()/1000);if(occurrences.merge(k,1,Integer::sum)<=existing.getOrDefault(k,0))continue;rows.add(e);}rows.sort(Comparator.comparingLong(Entry::time));int regularChars=0,globalChars=0,regularCount=0,globalCount=0,officialCount=0,officialChars=0;var retained=new ArrayList<Entry>();for(int i=rows.size()-1;i>=0;i--){var e=rows.get(i);if(e.channelKind().equals("official")){if(officialCount>=500||officialChars+e.text().length()>250_000)continue;officialCount++;officialChars+=e.text().length();}else if(e.channelKind().startsWith("favorite-")){if(globalCount>=1000||globalChars+e.text().length()>500_000)continue;globalCount++;globalChars+=e.text().length();}else{if(regularCount>=10000||regularChars+e.text().length()>4_000_000)continue;regularCount++;regularChars+=e.text().length();}retained.add(e);}Collections.reverse(retained);return List.copyOf(retained);}

 private static boolean valid(Entry e,String a){if(e==null||!a.equals(e.account())||e.peer()==null||e.text()==null||e.text().isEmpty()||e.text().length()>2000||e.time()<=0)return false;return switch(e.channelKind()){case "official"->e.peer().equals("官方");case "private"->e.peer().matches("[A-Za-z0-9_]{1,16}");case "favorite-global","favorite-trade","favorite-end","favorite-nether"->e.scope()!=null&&e.scope().matches("[A-Za-z0-9_]{1,16}")&&e.senderId().equals(e.scope())&&e.peer().equals("收藏:"+e.scope());case "land","nation"->scopeValid(e.scope())&&e.senderId().matches("[A-Za-z0-9_]{1,16}")&&e.peer().equals((e.channelKind().equals("land")?"领地:":"国家:")+e.scope());default->false;};}
 private static String key(Entry e,long second){return e.channelKind()+"\0"+e.originKind()+"\0"+e.peer().toLowerCase(Locale.ROOT)+"\0"+e.senderId()+"\0"+e.outgoing()+"\0"+second+"\0"+e.text();}
}
